const SLEEP_TIMER_WARNING_MINUTES=12*60,SLEEP_TIMER_CONFIRM_MINUTES=16*60,SLEEP_TIMER_MAX_ADJUST_MINUTES=48*60;
function familyLogSubjectKind(value:unknown){const kind=String(value||'ADULT').toUpperCase();return Object.prototype.hasOwnProperty.call(FAMILY_LOG_SUBJECT_META,kind)?kind:'OTHER';}
function familyLogDefaultTypes(kind:unknown){return [...(FAMILY_LOG_DEFAULT_TYPES[familyLogSubjectKind(kind)]||FAMILY_LOG_DEFAULT_TYPES.OTHER)];}
function familyLogEnabledTypes(subject:Row|undefined|null){if(!subject)return [...FAMILY_LOG_TYPES];const raw=String(subject.enabled_types_json||'').trim();if(raw){try{const parsed=JSON.parse(raw);if(Array.isArray(parsed)){const out=[...new Set(parsed.map(x=>String(x||'').toUpperCase()).filter(x=>FAMILY_LOG_SUBJECT_TYPES.includes(x)))];if(out.length)return out;}}catch{}}return familyLogDefaultTypes(subject.subject_kind);}
