function familyLogSubjectIcon(subject:Row|undefined|null){if(subject?.icon)return String(subject.icon);return FAMILY_LOG_SUBJECT_META[familyLogSubjectKind(subject?.subject_kind)]?.icon||'👤';}
function supportsDedicatedSleep(kind:unknown){return ['BABY','CHILD'].includes(familyLogSubjectKind(kind));}
function familyQuickChoreWeekdayBit(date:string){const day=new Date(`${date}T12:00:00+09:00`).getUTCDay();return day===0?64:1<<(day-1);}
function normalizeMilkAmountPresets(value:unknown):number[]{if(!Array.isArray(value)||value.length<1||value.length>6)throw new BadRequest('ミルク量の候補は1〜6件で指定してください。');const values=value.map(Number);if(values.some(v=>!Number.isInteger(v)||v<1||v>2000))throw new BadRequest('ミルク量は1〜2000mlの整数で指定してください。');return [...new Set(values)];}
async function ensureFamilyLogMemberSubjects(ctx:AppContext,familyId:number,createdBy:number){const now=nowJst();await ctx.env.DB.prepare(`INSERT INTO family_log_subjects(family_id,member_id,name,subject_kind,birth_date,icon,active,created_by,created_at,updated_at,enabled_types_json,auto_complete_linked_task)
 SELECT mm.family_id,mm.id,mm.name,CASE WHEN upper(COALESCE(mm.member_type,'ADULT'))='BABY' THEN 'BABY' WHEN upper(COALESCE(mm.member_type,'ADULT')) IN ('CHILD','KID') THEN 'CHILD' ELSE 'ADULT' END,NULL,mm.icon,1,?,COALESCE(mm.created_at,?),?,NULL,CASE WHEN upper(COALESCE(mm.member_type,'ADULT')) IN ('BABY','CHILD','KID') THEN 1 ELSE 0 END FROM members mm WHERE mm.family_id=? AND mm.active=1 AND NOT EXISTS(SELECT 1 FROM family_log_subjects s WHERE s.family_id=mm.family_id AND s.member_id=mm.id)`).bind(createdBy,now,now,familyId).run();}

