 const managementSubjects=subjects.results.map(subject=>`<div class="family-log-management-row"><span>${esc(familyLogSubjectIcon(subject))} <strong>${esc(subject.name)}</strong><small>${esc(FAMILY_LOG_SUBJECT_META[familyLogSubjectKind(subject.subject_kind)]?.label||'対象')}</small></span><button type="button" class="btn gray small family-log-subject-edit" data-id="${subject.id}">編集</button></div>`).join(''),weekdayLabels=['月','火','水','木','金','土','日'],weekdaySummary=(mask:number)=>weekdayLabels.filter((_,i)=>(mask&(1<<i))!==0).join(' ')||'表示なし',managementChores=quickChores.results.map(chore=>`<div class="family-log-management-row family-chore-management-row"><span><strong>${esc(chore.icon||'✨')} ${esc(chore.name)}</strong><small>${esc(weekdaySummary(Number(chore.weekday_mask??127)))}${Number(chore.active)?'':' · 非表示'}</small></span><button type="button" class="btn gray small family-quick-chore-edit" data-id="${chore.id}">編集</button></div>`).join('');
 const managementBody=`<div class="page-head family-log-head family-log-management-head"><h1>🐣 家族ログ管理</h1><a class="family-log-back-icon" href="/app/settings.php" aria-label="管理に戻る" title="管理に戻る">←</a></div><div class="card"><div class="section-head"><h2>記録対象・表示項目</h2>${familyLogIsAdmin?'<button type="button" class="btn small" id="familyLogSubjectOpen">＋ 対象追加</button>':''}</div>${managementSubjects}</div><div class="card family-log-settings-row"><button type="button" id="familyLogSettingsOpen" ${familyLogIsAdmin?'':'disabled'}><strong>大人ログ</strong><span>${showAdultLogs?'ON':'OFF'} ›</span></button></div><div class="card"><div class="section-head"><h2>🧹 ちょこっと家事</h2>${canManageQuickChores?'<button type="button" class="btn small" id="familyQuickChoreAdd">＋ 項目</button>':''}</div><div class="family-log-management-actions">${managementChores}</div></div><div class="card settings-links"><div class="section-link"><div><h2>📥 データインポート</h2><p class="small">データの取込とインポート履歴を管理します。</p></div><a class="btn gray" href="/app/family_log_import.php">開く</a></div></div>`;
 const dailyBody=`<div class="page-head family-log-head"><h1>🐣 家族ログ</h1><a class="family-log-gear" href="/app/settings_family_log.php" aria-label="家族ログ設定" title="家族ログ設定">⚙️</a></div><div class="card"><a class="btn" href="/app/child_journal.php">📔 成長日記</a><p class="small">立った・歩いた・歯・身長・体重など、残したい成長だけを月ごとに振り返れます。</p></div>${subjectChips}<div class="family-log-date-head"><a href="/app/family_log.php?date=${prev}${subjectQuery}" aria-label="前の日">‹</a><label><span>${esc(selectedDate.slice(5).replace('-','/'))}</span><input type="date" value="${selectedDate}" onchange="location.href='/app/family_log.php?date='+this.value+'${subjectQuery}'"></label><a href="/app/family_log.php?date=${next}${subjectQuery}" aria-label="次の日">›</a></div>${selectedSubject||adultAggregate||!quickChoreHtml?'':`<section class="family-quick-chore-card"><h2>🧹 ちょこっと家事</h2><div class="family-quick-chore-grid">${quickChoreHtml}</div></section>`}${overviewQuickHtml?`<div class="family-log-overview-quick">${overviewQuickHtml}</div>`:''}${quickButtons?`<div class="family-log-quick-card"><div class="family-log-quick-grid">${quickButtons}</div></div>`:''}${sleepRunningHtml}<details class="card family-log-timer-card"${timerHtml?' open':''}><summary>▶ ⏱ タイマー</summary>${timerHtml}${timerStartHtml}</details>${selectedSubject||adultAggregate?'':choreAggregateHtml}${dashboardHtml}<div class="card family-log-timeline"><div class="section-head"><h2>履歴</h2><form method="get" class="family-log-history-filters"><input type="hidden" name="date" value="${selectedDate}"><input type="hidden" name="subject" value="${adultAggregate?'adult':selectedSubject||''}"><select name="type" aria-label="種類" onchange="this.form.submit()"><option value="">すべて</option>${quickTypes.map(type=>`<option value="${type}" ${timelineType===type?'selected':''}>${FAMILY_LOG_TYPE_META[type].icon} ${FAMILY_LOG_TYPE_META[type].label}</option>`).join('')}<option value="MEMO" ${timelineType==='MEMO'?'selected':''}>📝 その他</option></select>${(adultAggregate||!selectedSubject)?`<select name="recorder" aria-label="記録者" onchange="this.form.submit()"><option value="0">記録者：すべて</option>${members.results.map(member=>`<option value="${member.id}" ${recorderFilter===Number(member.id)?'selected':''}>${esc(member.name)}</option>`).join('')}</select>`:`<input type="hidden" name="recorder" value="0">`}</form></div>${rowHtml||'<p class="empty">記録はありません。</p>'}<nav class="family-log-pagination">${timelinePage>1?`<a class="btn gray" href="?date=${selectedDate}${subjectQuery}&recorder=${recorderFilter}&type=${timelineType}&page=${timelinePage-1}${rangeQuery}">前へ</a>`:''}${timelineHasMore?`<a class="btn gray" href="?date=${selectedDate}${subjectQuery}&recorder=${recorderFilter}&type=${timelineType}&page=${timelinePage+1}${rangeQuery}">さらに読み込む</a>`:''}</nav></div>`;
 const sharedControls=`<div class="family-log-backdrop" id="familyLogModal" aria-hidden="true"><div class="family-log-sheet family-log-record-sheet"><div class="section-head"><h2 id="familyLogModalTitle">記録を追加</h2><button type="button" class="btn gray small" id="familyLogClose">×</button></div><form id="familyLogForm" class="family-log-record-form"><input type="hidden" name="id"><div class="family-log-primary-fields"><div id="familyLogTypeControl"><label>種類</label><select name="log_type">${FAMILY_LOG_TYPES.map(type=>`<option value="${type}">${FAMILY_LOG_TYPE_META[type].icon} ${FAMILY_LOG_TYPE_META[type].label}</option>`).join('')}</select></div><div id="familyLogSubjectControl"><label>対象</label><select name="subject_id"><option value="0">家族共通</option>${subjects.results.filter(s=>showAdultLogs||familyLogSubjectKind(s.subject_kind)!=='ADULT').map(s=>`<option value="${s.id}">${esc(familyLogSubjectIcon(s))} ${esc(s.name)}</option>`).join('')}</select></div><div id="familyLogSubjectChip" class="family-log-subject-chip" hidden></div><label class="family-log-datetime-row"><span>日時</span><input type="datetime-local" name="occurred_at" required></label></div><div id="familyLogDetailWrap"><label>詳細</label><div id="familyLogDetailChoices" class="family-log-detail-choices"></div><select name="detail_code"><option value="">指定なし</option></select></div><div id="familyLogAmountWrap"><label id="familyLogAmountLabel">値</label><div id="familyLogMilkPresets" class="family-log-preset-values" hidden></div><div class="family-log-value-input"><input type="number" name="amount"><span id="familyLogAmountUnit"></span><input type="hidden" name="unit"></div></div><div id="familyLogDurationWrap"><label id="familyLogDurationLabel">時間</label><div class="family-log-value-input"><input type="number" name="duration_minutes" min="0" max="10080" step="1"><span>分</span></div></div><div id="familyLogTextWrap"><label id="familyLogTextLabel">内容</label><input name="value_text" maxlength="255"></div><details id="familyLogAdvanced" class="family-log-advanced"><summary>▶ 詳細</summary><label>関連タスク・イベント（任意）</label><select name="linked_target"><option value="">なし</option>${linkOptions.map(x=>`<option value="${esc(x.value)}">${esc(x.label)}</option>`).join('')}</select><label>メモ</label><textarea name="note" maxlength="2000"></textarea><div id="familyLogProvenance" class="meta family-log-provenance" hidden></div></details><div id="familyLogStatus" class="small" aria-live="polite"></div><div class="family-log-form-actions"><button type="submit">保存する</button><button type="button" class="btn danger" id="familyLogDelete">削除</button></div></form></div></div><div class="family-log-backdrop" id="familyLogSubjectModal" aria-hidden="true"><div class="family-log-sheet small-sheet"><div class="section-head"><h2 id="familyLogSubjectTitle">記録対象を追加</h2><button type="button" class="btn gray small" id="familyLogSubjectClose">×</button></div><form id="familyLogSubjectForm"><input type="hidden" name="id"><label>名前</label><input name="name" maxlength="80" required placeholder="例：はる、赤ちゃん"><label>画面タイプ</label><select name="subject_kind"><option value="BABY">👶 赤ちゃん</option><option value="CHILD">🧒 子ども</option><option value="ADULT">👤 大人</option><option value="PET">🐾 ペット</option><option value="OTHER">⭐ その他</option></select><label>生年月日（任意）</label><input type="date" name="birth_date"><div class="family-log-type-setting-head"><label>表示する記録項目</label><div class="family-log-presets"><button type="button" class="btn gray small family-log-pet-preset" data-preset="CAT">🐱 猫向け</button><button type="button" class="btn gray small family-log-pet-preset" data-preset="DOG">🐶 犬向け</button><button type="button" class="btn gray small" id="familyLogPresetApply">おすすめ</button></div></div><div class="choice-list family-log-type-choice-grid">${subjectTypeChoices}</div><p class="small" id="familyLogSubjectGuide">対象タイプごとのおすすめ項目を使えます。</p><label class="checkrow family-log-overview-toggle"><input type="checkbox" name="show_on_family_overview" id="familyLogShowOverview"><span>「すべて」にこの対象の記録を表示する</span></label><div id="familyLogOverviewTypes" hidden><label>「すべて」に表示する項目</label><div class="choice-list family-log-type-choice-grid">${FAMILY_LOG_SUBJECT_TYPES.map(type=>`<label class="checkrow family-log-type-choice"><input type="checkbox" name="overview_quick_types" value="${type}"><span>${FAMILY_LOG_TYPE_META[type].icon} ${FAMILY_LOG_TYPE_META[type].label}</span></label>`).join('')}</div></div><label class="checkrow family-log-auto-complete"><input type="checkbox" name="auto_complete_linked_task" id="familyLogAutoComplete"><span>この対象の記録時、関連タスクを記録した人の完了として反映する</span></label><p class="small">赤ちゃん・子ども・ペットではおすすめONです。担当者が未設定なら記録者を担当者として追加します。別の担当者が設定済みの場合は勝手に変更しません。</p><div id="familyLogSubjectLinked" class="notice" style="display:none"></div><section class="family-log-quick-manage" id="familyLogQuickManage"><div class="section-head"><h3>クイック記録</h3><button type="button" class="btn gray small" id="familyLogQuickAdd">＋ クイック記録</button></div><div id="familyLogQuickRows"></div><p class="small">ワンタッチ・入力して記録・睡眠開始/終了を、対象ごとに編集できます。</p></section><button type="button" class="btn secondary" id="familyLogSubjectPromote" style="display:none">LINE本登録へ招待</button><div id="familyLogSubjectPromoteOut" class="notice" style="display:none"></div><div id="familyLogSubjectStatus" class="small" aria-live="polite"></div><div class="family-log-form-actions"><button type="submit">保存する</button><button type="button" class="btn danger" id="familyLogSubjectDisable">対象を非表示</button></div></form><p class="small">家族メンバーは自動的に対象として表示されます。赤ちゃん・子どもは後から「LINE本登録へ招待」で同じ記録対象を家族メンバーへ引き継げます。</p></div></div>${canManageQuickChores?`<div class="family-log-backdrop" id="familyQuickChoreModal" aria-hidden="true"><div class="family-log-sheet small-sheet"><div class="section-head"><h2 id="familyQuickChoreTitle">家事項目を追加</h2><button type="button" class="btn gray small" id="familyQuickChoreClose">×</button></div><form id="familyQuickChoreForm"><input type="hidden" name="id"><label>アイコン</label><input name="icon" maxlength="8" value="✨" placeholder="✨"><label>名前（1〜8文字）</label><input name="name" maxlength="80" required placeholder="例：トイレ掃除"><p class="small">8文字以内がおすすめです。既存の長い名前は自動で切断しません。</p><label>表示曜日</label><div class="family-chore-weekdays">${weekdayLabels.map((label,i)=>`<label><input type="checkbox" name="weekday" value="${1<<i}" checked><span>${label}</span></label>`).join('')}</div><div id="familyQuickChoreStatus" class="small" aria-live="polite"></div><div class="family-log-form-actions"><button type="submit">保存する</button><button type="button" class="btn danger" id="familyQuickChoreDisable">非表示</button></div></form><div class="family-quick-chore-manage"><div class="section-head"><h3>表示順</h3><span class="small">矢印で移動</span></div><div id="familyQuickChoreOrder"></div><div id="familyQuickChoreHidden"></div></div></div></div>`:''}${familyLogIsAdmin?`<div class="family-log-backdrop" id="familyLogSettingsModal" aria-hidden="true"><div class="family-log-sheet small-sheet"><div class="section-head"><h2>⚙️ 表示設定</h2><button type="button" class="btn gray small" id="familyLogSettingsClose">×</button></div><form id="familyLogSettingsForm"><label class="checkrow"><input type="checkbox" name="show_adult_logs" ${showAdultLogs?'checked':''}><span>大人の記録を表示する</span></label><label>ミルク量の候補（1〜6件、ml）</label><input name="milk_amount_presets" inputmode="numeric" value="${milkAmountPresets.join(', ')}" placeholder="160, 240"><p class="small">OFFでも大人の対象・過去ログ・メンバー連携は削除されません。</p><div id="familyLogSettingsStatus" class="small" aria-live="polite"></div><button type="submit">保存する</button></form></div></div>`:''}<script type="application/json" id="familyLogPayload">${payload}</script><script src="/assets/family-log.js?v=${APP_VERSION}"></script>`;
 const aiEntry=!managementMode&&familyLogIsAdmin?`<details class="family-ai-query"><summary>✨ Family AI</summary><form id="familyAiForm"><input name="question" maxlength="500" placeholder="質問、または予定・記録の追加" required><button type="submit">送る</button></form><div id="familyAiAnswer" class="small" aria-live="polite"></div><div id="familyAiConfirm" class="actions" hidden><button type="button" id="familyAiExecute">実行</button><button type="button" class="btn gray" id="familyAiCancel">キャンセル</button></div></details><script type="application/json" id="familyAiPayload">${JSON.stringify({csrf:ctx.session.csrfToken||''})}</script><script src="/assets/family-ai.js?v=${APP_VERSION}"></script>`:'';
 return html(layout(managementMode?'家族ログ管理':'家族ログ',(managementMode?managementBody:dailyBody)+aiEntry+sharedControls,managementMode?'/app/settings.php':'/app/family_log.php'));
